import{_ as a,c as r,o as t,ae as o}from"./chunks/framework.Ck3L_38O.js";const f=JSON.parse('{"title":"목돈 모으기","description":"","frontmatter":{"title":"목돈 모으기","date":"2025-05-28T23:00+09:00","tags":["재테크","파킹통장","CMA","ISA"]},"headers":[],"relativePath":"posts/raising-money.md","filePath":"posts/raising-money.md","lastUpdated":1759329303000}'),n={name:"posts/raising-money.md"};function d(s,e,i,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<p>사회초년생이라도 목돈을 모으기 위한 여러가지 방법에 대해서 알아두자.</p><h4 id="적당한-소비" tabindex="-1">적당한 소비 <a class="header-anchor" href="#적당한-소비" aria-label="Permalink to &quot;적당한 소비&quot;">​</a></h4><p>목돈을 모으기 위해 가장 중요한 일은 <code>내 근로 소득 기준에서 적당한 소비 패턴을 갖는 것</code>이다. 월 평균 소비액을 계산해보면 내 월급 중에서 얼마나 저축할 수 있는지 알 수 있다. 재테크 전문가들은 <a href="https://youtu.be/YJz5e3wioaA?si=TTtR6lk2AE5K4_dy&amp;t=255" target="_blank" rel="noreferrer">월급의 절반을 저축해야한다고 말하는데</a> 부모님과 함께 거주하는 <code>캥거루족은 월세 지출이 없으므로 월급의 70% 이상까지 저축</code>하는 목표를 가질 수 있다. 본인만의 저축, 비상금, 투자 금액의 비율을 설정하도록 하자.</p><h4 id="청년도약계좌" tabindex="-1">청년도약계좌 <a class="header-anchor" href="#청년도약계좌" aria-label="Permalink to &quot;청년도약계좌&quot;">​</a></h4><p><code>만 34세 이하 청년</code>들은 청년도약계좌를 개설하여 <code>매달 70만원을 납입하면 5년동안 최대 5천만원</code>을 모을 수 있다. 근로 소득이 높은 청년이라서 정부기여금이 없더라도 <code>이자소득에 대해서 비과세 혜택을 제공</code>하기 때문에 반드시 개설해서 최우선으로 납입하고 나머지 저축 가능 금액이 있다면 다른 적금 상품 또는 ISA 계좌에 납입하자. 하나은행의 <a href="https://new-m.pay.naver.com/savings/detail/13900d18ba6d470fa4ac9b1ca352210b" target="_blank" rel="noreferrer">급여하나 월복리 적금</a>이 청년우대금리를 제공하므로 그나마 금리가 높은 적금 상품이라 추천한다.</p><h4 id="금융-투자를-위한-isa-계좌" tabindex="-1">금융 투자를 위한 ISA 계좌 <a class="header-anchor" href="#금융-투자를-위한-isa-계좌" aria-label="Permalink to &quot;금융 투자를 위한 ISA 계좌&quot;">​</a></h4><p>ISA 계좌는 목돈을 모으면서도 다양한 금융 상품에 투자하여 운용 수익까지 얻을 수 있는 <code>만능 통장</code>이다. 3년이라는 의무 가입 기간이 지나면 <code>금융 소득에 대해 200만원까지 비과세 혜택을 제공하고 나머지 수익에 대해서는 9.9%로 분리 과세</code>까지 된다. 그러니까, 일반적인 예적금 상품의 이자 소득세가 15.4%인 점을 감안하면 과세 이연과 저율 과세된다는 점이 유용하다. 본인에게 적합한 적금 상품이 없고 금리까지 낮다면 ISA 계좌로 운용 수익을 내기까지 5년 이하로 가정하고 목돈을 모아보도록 하자.</p><p>매년 2천만원까지 납입할 수 있는 한도가 있는데 적립하고 남은 금액은 이월되기 때문에 당장 ISA 계좌를 활용하지 않더라도 미리 개설해두면 2천만원이 넘는 목돈을 한번에 납입해서 예금처럼 운용할 수도 있다. ISA 계좌에 납입한 적립금으로 다양한 금융 상품에 투자할 수 있지만 처음에는 만기 기대수익률을 보장하는 <a href="https://www.youtube.com/watch?v=FklLLnNMxrU" target="_blank" rel="noreferrer">만기채권형 ETF 상품을 추천</a>한다.</p><h4 id="짠테크-소소한-이자" tabindex="-1">짠테크! 소소한 이자 <a class="header-anchor" href="#짠테크-소소한-이자" aria-label="Permalink to &quot;짠테크! 소소한 이자&quot;">​</a></h4><p>파킹통장과 CMA 계좌는 일반적인 입출금 통장과 다르게 거치된 예치금 기준의 <code>하루 이자를 모아서 한달마다 지급</code>해준다. 회사에서 급여로 입금된 날로부터 카드 대금 결제일 또는 적금 자동 이체일이 다가올때까지 하루 이자를 받을 수 있다. 또한, 월급의 10%에 해당되는 비상금을 사용하지 않았다면 한달 이자를 지급받아 생활비 또는 투자금으로 사용할 수 있다. 만약, 예치금이 소액이라면 <code>일정 금액에 대해 고금리 이자를 제공하는 파킹 통장을 개설하는 것을 추천</code>한다.</p><ul><li><a href="https://new-m.pay.naver.com/savings/detail/e6bb080c0b08a8a4421ba7525cdd23a8" target="_blank" rel="noreferrer">우리은행의 우월한 월급 통장</a> → 200만원 이하</li><li><a href="https://new-m.pay.naver.com/savings/detail/77df12990f1ec2d40992ee8cd6d00cae" target="_blank" rel="noreferrer">OK저축은행의 OK짠테크통장Ⅱ</a> → 500만원 이하</li><li><a href="https://new-m.pay.naver.com/savings/detail/f7752ec2fea16af8554c64fb63ebb79b" target="_blank" rel="noreferrer">키움저축은행의 더 키움 파킹통장</a> → 1,000만원 초과</li></ul><p>파킹통장과 함께 한달 적금처럼 <code>매일마다 납입하는 적금 상품을 개설</code>하는 것도 나쁘지 않다. <a href="https://toss.im/tossfeed/article/guide-raising-seed-money" target="_blank" rel="noreferrer">시드머니를 만드는 짠테크</a> 방안 중에서 적금 풍차돌리기는 신경써야하는 부분이 많기 때문에 개인적으로 좋은 방법은 아닌 듯 하다.</p><p>다음에는 노후자금마련을 위한 연금저축에 대해서 ㅁㅁㅂㄲ ?</p>',13)])])}const _=a(n,[["render",d]]);export{f as __pageData,_ as default};
